def build_article(art):
    sections_html = ""
    for h2, content in art["sections"]:
        sections_html += '\n    <section class="post-section">\n      <h2>' + h2 + '</h2>\n      <p>' + content + '</p>\n    </section>\n'
    og_url = "https://smithribbon.com/" + art["slug"] + ".html"
    short_d = art["description"][:197] + "..."
    html = TEMPLATE.format(
        title=art["short_title"],
        short_d=short_d,
        keywords=art["keywords"],
        og_url=og_url,
        datetime=art["datetime"],
        category=art["category"],
        date_label=art["date_label"],
        description=art["description"],
        sections_html=sections_html,
        footer_blurb=art["footer_blurb"],
        module_count=art["module_count"],
        footer_module=art["footer_module"],
        word_count=art["word_count"],
    )
    out = os.path.join(BASE, art["slug"] + ".html")
    with open(out, "w", encoding="utf-8") as f:
        f.write(html)
    print("[OK] Created:", out)
    return out, art["slug"], art["category"], art["short_title"], art["date_label"], art["description"]


def update_blog_list(slug, category, short_title, description, date_label):
    card = '\n        <article class="blog-card">\n            <span class="blog-tag">' + category + '</span>\n            <h3><a href="' + slug + '.html">' + short_title + '</a></h3>\n            <p>' + description[:240] + '...</p>\n            <div class="blog-meta">' + date_label + '</div>\n        </article>\n'
    for blog in ["en-blog.html", "blog.html"]:
        bp = os.path.join(BASE, blog)
        if not os.path.exists(bp):
            continue
        with open(bp, "r", encoding="utf-8") as f:
            content = f.read()
        inserted = False
        for pat in [r'(<section class="blog-hero">.*?</section>)', r'(<div class="blog-hero">.*?</div>)']:
            if re.search(pat, content, flags=re.DOTALL):
                content = re.sub(pat, r'\g<0>' + card, content, count=1, flags=re.DOTALL)
                inserted = True
                break
        if not inserted:
            content = re.sub(r'(</h1>)', r'\1' + card, content, count=1)
        with open(bp, "w", encoding="utf-8") as f:
            f.write(content)
        print("[OK] Updated:", blog)


def update_sitemap(slug, date_iso):
    sp = os.path.join(BASE, "sitemap.xml")
    with open(sp, "r", encoding="utf-8") as f:
        sc = f.read()
    new_url = '\n  <url>\n    <loc>https://smithribbon.com/' + slug + '.html</loc>\n    <lastmod>' + date_iso + '</lastmod>\n    <changefreq>monthly</changefreq>\n    <priority>0.8</priority>\n  </url>'
    if "</urlset>" in sc:
        sc = sc.replace("</urlset>", new_url + "\n</urlset>")
    else:
        sc = sc + new_url
    with open(sp, "w", encoding="utf-8") as f:
        f.write(sc)
    print("[OK] Updated: sitemap.xml")


if __name__ == "__main__":
    for art in ARTICLES:
        out, slug, category, short_title, date_label, description = build_article(art)
        update_blog_list(slug, category, short_title, description, date_label)
        update_sitemap(slug, DATE_ISO)
    print("\nDone.")